#include "finite.hpp"
int main(int argc,char**argv){try{ec::check(argc==3,"workload outputdir");Graph graph(argv[1]);ec::check(graph.w.h.costs>0&&graph.w.h.costs<=16,"COST_INDEX_WIDTH");ec::check(graph.edge.size()<uint64_t(1)<<32,"EDGE_OFFSET32");ec::check(graph.w.h.nodes<=4194304&&graph.w.h.cells<=32768&&graph.w.h.jobs<=64,"NATIVE_GEOMETRY");for(auto desc:graph.edge){unsigned n=desc&0xfffffff;ec::check(n<graph.w.h.nodes,"DESCRIPTOR_NODE");ec::check(graph.w.node[n].cost<graph.w.h.costs&&graph.w.node[n].cost<16,"USED_NATIVE_COST");ec::check((desc>>28)==graph.w.node[n].cost,"COST_DESCRIPTOR_TRUNCATION");}std::filesystem::create_directories(argv[2]);std::string dir=argv[2];std::filesystem::create_directories(dir+"/q0");std::filesystem::create_directories(dir+"/qLast");auto first=std::make_unique<ec::Model>(graph,0,dir+"/q0");auto last=std::make_unique<ec::Model>(graph,graph.w.h.jobs-1,dir+"/qLast");using R=std::pair<ec::T,ec::T>;ec::T nline=(graph.w.h.nodes+3)/4,outstride=Graph::align((graph.w.h.cells+3)/4);std::array<R,7>ranges{{{0,(graph.w.h.nodes+4)/4},{graph.edgebase,graph.edgebase+(graph.edge.size()+7)/8},{graph.metabase,graph.metabase+graph.w.h.jobs*graph.metastride},{first->labelbase,first->labelbase+nline},{first->scratchbase,first->scratchbase+nline},{first->outputbase,first->outputbase+graph.w.h.jobs*outstride},{first->costbase,first->costbase+(graph.w.h.costs+3)/4}}};for(unsigned i=0;i<7;++i){ec::check(ranges[i].first<=ranges[i].second&&ranges[i].second<=uint64_t(1)<<32,"PHYSICAL_LINE_RANGE");ec::check(!(ranges[i].first&31),"PHYSICAL_REGION_STRIPE_ALIGNMENT");if(i)ec::check(ranges[i-1].second<=ranges[i].first,"PHYSICAL_REGION_OVERLAP");}ec::check(last->costbase==first->costbase,"COST_BASE_CHANGED_WITH_SAMPLE");ec::check(last->outputbase+(graph.w.h.cells+3)/4<=first->costbase,"LAST_OUTPUT_COST_OVERLAP");ec::check(last->outputbase-first->outputbase==(graph.w.h.jobs-1)*outstride,"SAMPLE_OUTPUT_ALIAS");std::ofstream o(dir+"/admission.json");o<<"{\"all_pass\":true,\"nodes\":"<<graph.w.h.nodes<<",\"prepared_edges\":"<<graph.edge.size()<<",\"costs\":"<<graph.w.h.costs<<",\"cost_read_beats_per_sample\":"<<(graph.w.h.costs+3)/4<<",\"sample_output_stride_lines\":"<<outstride<<",\"ranges_in_32B_lines\":[";for(unsigned i=0;i<7;++i){if(i)o<<',';o<<'['<<ranges[i].first<<','<<ranges[i].second<<']';}o<<"],\"range_names\":[\"row\",\"edge\",\"all_sample_metadata\",\"canonical\",\"scratch\",\"all_sample_output\",\"cost\"],\"initialization_parallel_floor_cycles\":16384,\"one_sample_clear_edge\":true,\"qualified_hardware_fit\":false}\n";std::cout<<"ADMISSION_PASS costs="<<graph.w.h.costs<<" beats="<<(graph.w.h.costs+3)/4<<" disjoint7regions allsamples usedcostindices offsets32\n";}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}return 0;}
